-- TiDB SQL editor version. Numbered 0238. Run after 0233 (the kitchen_rules table must exist).
-- One statement. Every table is cabinet_dealz.<table>.
-- Do not run this from an application. The owner pastes it in the TiDB editor.
-- Safe to re-run: INSERT IGNORE. Adds only the "Questions for Rich" reference rows (reference-only, no Designer behavior).
-- The admin Kitchen Rules list already shows these from the built-in catalog; the rows are needed so Rich can save answers in Notes.

-- 1
INSERT IGNORE INTO cabinet_dealz.kitchen_rules (
  ruleCode, category, title, ruleDescription, parameterJson, enforcementKind, sourceText,
  implementationStatus, enabledFlag, notesText, readsParameters
) VALUES
('rich-q-gap-in-run', 'Questions for Rich', 'A gap bigger than 3 inches in a run', 'NKBA: Silent on filler widths. Auto-Design today: A gap of 3 inches or less gets a filler automatically. A bigger gap, such as the 9 to 10 inches beside a range, is left open with no cabinet and no filler. Question for Rich: What do you put in a 4, 6, 9 or 12 inch gap: a wider filler, a 9 inch spice base, a drawer base, or move the run? What is the widest filler you will install?', '{}', 'reference', 'NKBA planning guidelines, owner rules, question for Rich', 'reference', 1, 'Rich''s answer: (not answered yet). Write what you do on a real job, and any number you use.', 0),
('rich-q-hood-bottom', 'Questions for Rich', 'How high above the cooktop does the hood go', 'NKBA: Guideline 18: 24 inches minimum to a protected noncombustible surface, 30 inches to combustible material or metal cabinets, or 24 inches with an approved hood. Follow the manufacturer for over-range microwaves. Auto-Design today: The owner rule says the hood bottom is 60 inches (24 inches over a 36 inch cooktop). Auto-Design applies 60 only to a 42 inch hood and places every other hood at 54 inches, 18 inches over the cooktop. The catalog hood entries say 66 inches. Gas hood manuals often say 30 inches. The 54 inch bottom is not arbitrary: the hood is 18 inches tall, so its top lands at 72 inches, exactly where the owner''s 24 inch bridge cabinet starts. Raising the hood to meet NKBA means moving or shortening that bridge. Question for Rich: Where do you hang a 30, 36 and 42 inch hood on gas and on electric? How do you handle the cabinet above the hood when the hood is raised to 24 or 30 inches over the cooktop?', '{}', 'reference', 'NKBA planning guidelines, owner rules, question for Rich', 'reference', 1, 'Rich''s answer: (not answered yet). Write what you do on a real job, and any number you use.', 0),
('rich-q-wall-cab-beside-hood', 'Questions for Rich', 'Wall cabinet next to a hood', 'NKBA: Silent. Auto-Design today: A 3/4 inch end panel is added on the side of a wall cabinet that faces the range or hood, flush against the hood. Question for Rich: Does the hood sit tight to the cabinet or with a gap? Do you put a panel or a filler there? How much space do you leave for the hood to be installed and serviced?', '{}', 'reference', 'NKBA planning guidelines, owner rules, question for Rich', 'reference', 1, 'Rich''s answer: (not answered yet). Write what you do on a real job, and any number you use.', 0),
('rich-q-range-landing', 'Questions for Rich', 'Counter on each side of the range', 'NKBA: Guideline 17: 12 inches on one side and 15 inches on the other at cooktop height. Where two landing areas are next to each other, use the longer one plus 12 inches (guideline 24). Auto-Design today: 15 inches of real base on both sides of the range, and nothing smaller than a 15 inch base against it. Question for Rich: Is 15 inches both sides right? Will you ever leave a range with a 9 or 12 inch cabinet or a filler beside it?', '{}', 'reference', 'NKBA planning guidelines, owner rules, question for Rich', 'reference', 1, 'Rich''s answer: (not answered yet). Write what you do on a real job, and any number you use.', 0),
('rich-q-dishwasher', 'Questions for Rich', 'Dishwasher placement and clearance', 'NKBA: Guideline 13: within 36 inches of the sink edge, with 21 inches of standing space at right angles to the dishwasher. Auto-Design today: The dishwasher goes beside the sink and is flagged against an inside corner; Auto-Design will not slide it more than 3 inches to clear the corner. Question for Rich: How far from a corner do you need a dishwasher so the door opens? Which side of the sink do you prefer? Do you want a panel beside it?', '{}', 'reference', 'NKBA planning guidelines, owner rules, question for Rich', 'reference', 1, 'Rich''s answer: (not answered yet). Write what you do on a real job, and any number you use.', 0),
('rich-q-sink-and-prep', 'Questions for Rich', 'Counter around the sink', 'NKBA: Guideline 11: 24 inches on one side and 18 inches on the other, at least 16 inches deep. Guideline 12: 36 inches wide by 24 inches deep of continuous counter for prep beside the sink. Auto-Design today: 24 and 18 inches of landing and a 36 inch prep counter are checked and flagged. They do not steer where cabinets are placed. Question for Rich: Is 24 and 18 enough in a small kitchen? What is the smallest prep counter you would sign off on?', '{}', 'reference', 'NKBA planning guidelines, owner rules, question for Rich', 'reference', 1, 'Rich''s answer: (not answered yet). Write what you do on a real job, and any number you use.', 0),
('rich-q-fridge-clearances', 'Questions for Rich', 'Space around the refrigerator', 'NKBA: Guideline 16: 15 inches of counter on the handle side, or 15 inches across an aisle within 48 inches. Auto-Design today: A 15 inch real cabinet is required between the range and the refrigerator, a hinge-side clearance of 2.5 inches is flagged against a wall, and panels are cut to 24 inches. Some sources cut panels to 25 inches and want the tall cabinet 25 inches deep. Question for Rich: What clearance do you leave on the hinge side and the top of a refrigerator? Do you cut panels to 24 or 25 inches?', '{}', 'reference', 'NKBA planning guidelines, owner rules, question for Rich', 'reference', 1, 'Rich''s answer: (not answered yet). Write what you do on a real job, and any number you use.', 0),
('rich-q-panels-when', 'Questions for Rich', 'When do exposed sides get a finished panel', 'NKBA: Silent. Auto-Design today: The owner rule says the Designer does not add panels on its own. Other rules and Auto-Design do add 3/4 inch panels at run ends, beside a window, beside the dishwasher and fridge, and beside a range. Question for Rich: On a real job which ends always get a panel, and which ones do you skip?', '{}', 'reference', 'NKBA planning guidelines, owner rules, question for Rich', 'reference', 1, 'Rich''s answer: (not answered yet). Write what you do on a real job, and any number you use.', 0),
('rich-q-wall-cabinet-heights', 'Questions for Rich', 'Wall cabinet bottom and top lines', 'NKBA: Silent on cabinet heights. Guideline 21: a microwave goes no higher than 54 inches to the bottom. Auto-Design today: Bottoms at 54 inches, runs topping at 96 inches, a 30 inch cabinet topping at 84. The owner also said 24 inch cabinets at 66 inches, which is stored and not applied. Question for Rich: What heights do you hang 30, 36 and 42 inch uppers at? Do you carry the top line to 96 inches with a stacker or crown? Where do 24 inch cabinets go?', '{}', 'reference', 'NKBA planning guidelines, owner rules, question for Rich', 'reference', 1, 'Rich''s answer: (not answered yet). Write what you do on a real job, and any number you use.', 0),
('rich-q-corners', 'Questions for Rich', 'Corners', 'NKBA: Guideline 29: at least one corner cabinet with a functional storage device. Auto-Design today: Auto-Design picks a diagonal corner, then the largest lazy Susan, then the largest blind corner that fits, with a 3 inch blind filler. Question for Rich: What corner do you choose in a small kitchen? How far do you pull a blind corner off the wall for the door to open?', '{}', 'reference', 'NKBA planning guidelines, owner rules, question for Rich', 'reference', 1, 'Rich''s answer: (not answered yet). Write what you do on a real job, and any number you use.', 0),
('rich-q-walkways', 'Questions for Rich', 'Aisles and walkways', 'NKBA: Guideline 6: 42 inches minimum for one cook, 48 inches for two, and 60 inches between opposing arms of a U-shaped kitchen. Guideline 3: work triangle legs 4 to 9 feet, total no more than 26 feet. Auto-Design today: Aisles and the work triangle are checked and flagged when the plan has the runs to check. Question for Rich: Where do you bend these numbers in tight kitchens, and where must they never be bent?', '{}', 'reference', 'NKBA planning guidelines, owner rules, question for Rich', 'reference', 1, 'Rich''s answer: (not answered yet). Write what you do on a real job, and any number you use.', 0),
('rich-q-what-designs-get-wrong', 'Questions for Rich', 'What do computer designs usually get wrong on site', 'NKBA: Not a guideline. Auto-Design today: Not applicable. Question for Rich: Which problems have you had to fix on the job most often after a design was done, starting with the most common?', '{}', 'reference', 'NKBA planning guidelines, owner rules, question for Rich', 'reference', 1, 'Rich''s answer: (not answered yet). Write what you do on a real job, and any number you use.', 0);
